[{"order":1,"type":"heading","text":"Writing Custom Modules and Plugins in Ansible (Python)"},{"order":2,"type":"paragraph","text":"While Ansible provides a vast library of built-in modules and plugins, advanced automation scenarios often require custom extensions. This tutorial covers how to write custom Ansible modules and plugins using Python."},{"order":3,"type":"subheading","text":"Directory Structure and Preparation"},{"order":4,"type":"paragraph","text":"Ansible automatically looks for custom modules and plugins in specific directory structures relative to your playbook or configured via ansible.cfg. For a standard project, create a structure with 'library' for modules and 'plugin_type' folders for plugins."},{"order":5,"type":"bullet_point","text":"library/: Contains custom Python modules."},{"order":6,"type":"bullet_point","text":"filter_plugins/: Contains custom Jinja2 filter plugins."},{"order":7,"type":"subheading","text":"Writing a Custom Ansible Module"},{"order":8,"type":"paragraph","text":"An Ansible module is a self-contained Python script executed on the target node. It receives arguments via JSON, performs tasks, and returns results in JSON format using the AnsibleModule class."},{"order":9,"type":"code","text":"#!/usr/bin/python

from ansible.module_utils.basic import AnsibleModule

def run_module():
    module_args = {
        "name": {"type": "str", "required": True},
        "new": {"type": "bool", "default": False}
    }

    result = {
        "changed": False,
        "original_message": "",
        "message": ""
    }

    module = AnsibleModule(
        argument_spec=module_args,
        supports_check_mode=True
    )

    if module.check_mode:
        module.exit_json(**result)

    result["original_message"] = module.params["name"]
    result["message"] = "Successfully processed {0}".format(module.params["name"])

    if module.params["name"] == "fail_test":
        module.fail_json(msg="You requested a failure", **result)

    result["changed"] = True
    module.exit_json(**result)

if __name__ == '__main__':
    run_module()"},{"order":10,"type":"subheading","text":"Writing a Custom Filter Plugin"},{"order":11,"type":"paragraph","text":"Plugins execute on the control node. Filter plugins manipulate data within templates or playbooks. Below is an example of a custom Jinja2 filter plugin that reverses strings."},{"order":12,"type":"code","text":"class FilterModule(object):
    def filters():
        return {
            'reverse_string': reverse_string
        }

def reverse_string(value):
    if not isinstance(value, str):
        return value
    return value[::-1]"},{"order":13,"type":"subheading","text":"Testing Custom Modules and Plugins"},{"order":14,"type":"paragraph","text":"To test your newly created module, place it inside the 'library' directory at the root of your playbook workspace and invoke it directly using an ad-hoc command or within a playbook task."},{"order":15,"type":"code","text":"ansible localhost -m custom_module_name -a "name=production new=true""}]
